panels.script:
const ngu = window.ngu;
const wrap = panel.querySelector('#tk-wrap');
function paint(state){
  if (!state || !state.open) {
    wrap.style.display = 'none';
    wrap.textContent = '';
    document.body.style.display = 'none';
    return;
  }
  const parts = [state.open + ' 张票'];
  if (state.running) parts.push(state.running + ' 在跑');
  if (state.delivered) parts.push(state.delivered + ' 待验收');
  if (state.stuck) parts.push(state.stuck + ' 卡住');
  let line = parts.join(' · ');
  if (state.attention && state.attention.length) line += '  ' + state.attention.join(' ');
  wrap.textContent = line;
  wrap.style.display = 'block';
  document.body.style.display = '';
}
function scan(text){
  if (typeof text !== 'string') return;
  const m = text.match(/<!--ticket-state (\{[^}]*\})-->/);
  if (!m) return;
  try { paint(JSON.parse(m[1])); } catch (e) {}
}
if (ngu && typeof ngu.on === 'function') {
  ngu.on('tool_end', function(ev){ scan(ev && ev.result); });
}
// 一开始就没有票：整帧收起（壳子收到 0 高度会连外框一起隐藏），不留空带。
document.body.style.display = 'none';
wrap.title = '票看板：来自主代理每次 ticket_* 调用的结果标记';
